      transition: background 0.15s;
    }

    .fs-item:hover {
      background: rgba(233, 84, 32, 0.15);
    }

    .fs-icon {
      width: 44px;
      height: 44px;
      margin-bottom: 6px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .folder-svg {
      width: 40px;
      height: 40px;
      fill: var(--ubuntu-orange);
    }

    .file-svg {
      width: 40px;
      height: 40px;
      fill: #eaeaea;
    }

    .fs-name {
      font-size: 12px;
      color: #eaeaea;
      word-break: break-all;
      line-height: 1.3;
    }

    .empty-folder {
      grid-column: 1 / -1;
      text-align: center;
      color: #666;
      font-size: 13px;
      margin-top: 40px;
    }

    /* Notepad App */
    #notepad-layout {
      display: flex;
      flex-direction: column;
      height: 100%;
    }

    #notepad-header {
      display: flex;
      background: #181818;
      border-bottom: 1px solid #2d2d2d;
      align-items: center;
      padding: 0 8px;
    }

    #tabs {
      display: flex;
      overflow-x: auto;
      gap: 4px;
      flex: 1;
    }

    .tab {
      display: flex;
      align-items: center;
      gap: 8px;
      background: var(--tab-bg);
      border: 1px solid rgba(255,255,255,0.03);
      border-bottom: none;
      padding: 6px 12px;
      border-top-left-radius: 6px;
      border-top-right-radius: 6px;
      font-size: 12px;
      cursor: pointer;
      color: #aaa;
      margin-top: 6px;
      max-width: 140px;
      white-space: nowrap;
    }

    .tab.active {
      background: var(--active-tab-bg);
      color: #fff;
      border-top: 2px solid var(--ubuntu-orange);
    }

    .tab-title {
      overflow: hidden;
      text-overflow: ellipsis;
    }

    .tab-close {
      font-weight: bold;
      opacity: 0.6;
      border-radius: 50%;
      width: 14px;
      height: 14px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .tab-close:hover {
      background: rgba(255, 255, 255, 0.15);
      opacity: 1;
    }

    #new-tab {
      background: none;
      border: none;
      color: #aaa;
      font-size: 18px;
      cursor: pointer;
      padding: 6px 12px;
      display: flex;
      align-items: center;
      outline: none;
    }

    #new-tab:hover {
      color: #fff;
    }

    #editor-container {
      flex: 1;
      background: #1e1e1e;
      padding: 12px;
    }

    #editor {
      width: 100%;
      height: 100%;
      background: transparent;
      border: none;
      color: #dfdbd2;
      font-family: 'Ubuntu Mono', Consolas, monospace;
      font-size: 14px;
      resize: none;
      outline: none;
      line-height: 1.5;
    }

    /* Scrollbars */
    ::-webkit-scrollbar {
      width: 8px;
      height: 8px;
    }
    ::-webkit-scrollbar-track {
      background: #111111;
    }
    ::-webkit-scrollbar-thumb {
      background: #3a3a3a;
      border-radius: 4px;
    }
    ::-webkit-scrollbar-thumb:hover {
      background: #505050;
    }
  </style>
</head>
<body>

  <div id="desktop">
    <!-- Top System Bar -->
    <div id="top-bar">
      <div class="left">
        <span style="font-weight: bold; color: var(--ubuntu-orange);">Ubuntu</span>
        <span>Activities</span>
      </div>
      <div class="center">
        <div id="clock">Oct 24 14:04</div>
      </div>
      <div class="right">
        <div class="sys-status">
          <span>📶</span>
          <span>🔋 100%</span>
          <span>user@ubuntu</span>
        </div>
      </div>
    </div>

    <!-- Taskbar / Dock -->
    <div id="taskbar">
      <!-- Files Launcher -->
      <button id="open-files" class="dock-icon" title="Files">
        <svg viewBox="0 0 24 24">
          <path d="M10 4H4c-1.11 0-2 .89-2 2v12c0 1.1.9 2 2 2h16c1.1 0 2-.9 2-2V8c0-1.11-.9-2-2-2h-8l-2-2z"/>
        </svg>
      </button>

      <!-- Notepad Launcher -->
      <button id="open-notepad" class="dock-icon" title="Notepad">
        <svg viewBox="0 0 24 24">
          <path d="M14 2H6c-1.1 0-1.99.9-1.99 2L4 20c0 1.1.89 2 1.99 2H18c1.1 0 2-.9 2-2V8l-6-6zm2 16H8v-2h8v2zm0-4H8v-2h8v2zm-3-5V3.5L18.5 9H13z"/>
        </svg>
      </button>
    </div>

    <!-- Files App Window -->
    <div id="files-window" class="window hidden">
      <div class="win-header">
        <div class="win-title">Files</div>
        <div class="win-controls">
          <button class="win-btn win-close" title="Close">×</button>
        </div>
      </div>
      <div class="win-content">
        <div class="files-nav">
          <button id="files-up" title="Go up to parent directory">
            <svg viewBox="0 0 24 24" style="width:14px; height:14px; fill:currentColor;"><path d="M4 12l1.41 1.41L11 7.83V20h2V7.83l5.58 5.59L20 12l-8-8-8 8z"/></svg>
            Up
          </button>
          <div id="files-path">/</div>
        </div>
        <div id="files-grid"></div>
      </div>
    </div>

    <!-- Notepad App Window -->
    <div id="notepad-window" class="window hidden">
      <div class="win-header">
        <div class="win-title">Notepad</div>
        <div class="win-controls">
          <button class="win-btn win-close" title="Close">×</button>
        </div>
      </div>
      <div class="win-content">
        <div id="notepad-layout">
          <div id="notepad-header">
            <div id="tabs"></div>
            <button id="new-tab" title="New Tab">+</button>
          </div>
          <div id="editor-container">
            <textarea id="editor" spellcheck="false" placeholder="Type your text here..."></textarea>
          </div>
        </div>
      </div>
    </div>

  </div>

  <script>
    /* ================= SYSTEM CLOCK ================= */
    function updateClock() {
      const clockEl = document.getElementById('clock');
      const now = new Date();
      const options = { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', hour12: false };
      clockEl.textContent = now.toLocaleDateString('en-US', options);
    }
    setInterval(updateClock, 1000);
    updateClock();


    /* ================= DRAG AND DROP & WINDOW FOREGROUND SYSTEM ================= */
    const windows = {
      files: document.getElementById('files-window'),
      notepad: document.getElementById('notepad-window')
    };

    let topZIndex = 100;

    function bringToFront(win) {
      topZIndex++;
      win.style.zIndex = topZIndex;
    }

    function openWindow(key) {
      const win = windows[key];
      win.classList.remove('hidden');
      bringToFront(win);
    }

    // Connect Launchers
    document.getElementById('open-files').addEventListener('click', () => openWindow('files'));
    document.getElementById('open-notepad').addEventListener('click', () => openWindow('notepad'));

    // Connect Close Controls
    document.querySelectorAll('.win-close').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const win = e.target.closest('.window');
        win.classList.add('hidden');
      });
    });

    // Bring clicked window to front
    document.querySelectorAll('.window').forEach(win => {
      win.addEventListener('mousedown', () => bringToFront(win));
    });

    // Window Draggability Handler
    document.querySelectorAll('.win-header').forEach(header => {
      header.addEventListener('mousedown', (e) => {
        const win = header.closest('.window');
        bringToFront(win);

        let shiftX = e.clientX - win.getBoundingClientRect().left;
        let shiftY = e.clientY - win.getBoundingClientRect().top;

        function moveAt(pageX, pageY) {
          let newLeft = pageX - shiftX;
          let newTop = pageY - shiftY;

          // Cap on top bar boundary
          if (newTop < 28) newTop = 28;

          win.style.left = newLeft + 'px';
          win.style.top = newTop + 'px';
        }

        function onMouseMove(event) {
          moveAt(event.clientX, event.clientY);
        }

        document.addEventListener('mousemove', onMouseMove);

        document.addEventListener('mouseup', () => {
          document.removeEventListener('mousemove', onMouseMove);
        }, { once: true });
      });

      header.ondragstart = () => false;
    });


    /* ================= FILES SYSTEM (STATIC REPLICA) ================= */
    const fsData = {
      name: '/',
      type: 'dir',
      children: {
        'bin': { type: 'dir', children: {} },
        'etc': { type: 'dir', children: {} },
        'home': {
          type: 'dir',
          children: {
            'user': {
              type: 'dir',
              children: {
                'Documents': {
                  type: 'dir',
                  children: {
                    'notes.txt': { type: 'file', content: 'Welcome to your local environment notes!' }
                  }
                },
                'Downloads': {
                  type: 'dir',
                  children: {
                    'setup.sh': { type: 'file', content: '#!/bin/bash\necho "Setting up things..."' }
                  }
                },
                'Pictures': {
                  type: 'dir',
                  children: {
                    'avatar.png': { type: 'file', content: 'PNG binary payload placeholder' }
                  }
                }
              }
            }
          }
        },
        'usr': { type: 'dir', children: {} },
        'var': { type: 'dir', children: {} }
      }
    };

    let currentPath = []; // Tracks location segments from root '/'

    function getNodeFromPath(pathArr) {
      let curr = fsData;
      for (const segment of pathArr) {
        if (curr.children && curr.children[segment]) {
          curr = curr.children[segment];
        } else {
          return null;
        }
      }
      return curr;
    }

    function renderFiles() {
      const container = document.getElementById('files-grid');
      const pathEl = document.getElementById('files-path');
      const upBtn = document.getElementById('files-up');

      // Update Path UI
      const pathStr = '/' + currentPath.join('/');
      pathEl.textContent = pathStr;

      // Handle Go Up state
      if (currentPath.length === 0) {
        upBtn.disabled = true;
        upBtn.style.opacity = '0.5';
        upBtn.style.cursor = 'not-allowed';
      } else {
        upBtn.disabled = false;
        upBtn.style.opacity = '1';
        upBtn.style.cursor = 'pointer';
      }

      container.innerHTML = '';
      const currentNode = getNodeFromPath(currentPath);

      if (!currentNode || currentNode.type !== 'dir') return;

      const entries = Object.keys(currentNode.children);

      if (entries.length === 0) {
        container.innerHTML = `<div class="empty-folder">This directory is empty</div>`;
        return;
      }

      entries.forEach(name => {
        const item = currentNode.children[name];
        const itemEl = document.createElement('div');
        itemEl.className = 'fs-item';
        itemEl.dataset.name = name;
        itemEl.dataset.type = item.type;

        // Custom SVGs for Directory vs File to match Ubuntu design beautifully
        const svgIcon = item.type === 'dir'
          ? `<svg class="folder-svg" viewBox="0 0 24 24"><path d="M10 4H4c-1.1 0-1.99.9-1.99 2L2 18c0 1.1.9 2 2 2h16c1.1 0 2-.9 2-2V8c0-1.1-.9-2-2-2h-8l-2-2z"/></svg>`
          : `<svg class="file-svg" viewBox="0 0 24 24"><path d="M14 2H6c-1.1 0-1.99.9-1.99 2L4 20c0 1.1.89 2 1.99 2H18c1.1 0 2-.9 2-2V8l-6-6zm2 16H8v-2h8v2zm0-4H8v-2h8v2zm-3-5V3.5L18.5 9H13z"/></svg>`;

        itemEl.innerHTML = `
          <div class="fs-icon">${svgIcon}</div>
          <div class="fs-name">${name}</div>
        `;

        container.appendChild(itemEl);
      });
    }

    // Navigation via double click
    document.getElementById('files-grid').addEventListener('dblclick', (e) => {
      const item = e.target.closest('.fs-item');
      if (!item) return;

      const name = item.dataset.name;
      const type = item.dataset.type;

      if (type === 'dir') {
        currentPath.push(name);
        renderFiles();
      } else {
        const currentNode = getNodeFromPath(currentPath);
        const fileNode = currentNode.children[name];
        alert(`File: ${name}\n\n${fileNode.content || '(empty)'}`);
      }
    });

    // Parent Directory navigation button
    document.getElementById('files-up').addEventListener('click', () => {
      if (currentPath.length > 0) {
        currentPath.pop();
        renderFiles();
      }
    });


    /* ================= NOTEPAD SYSTEM (PERSISTENT & TABBED) ================= */
    let notepadState = {
      tabs: [],
      activeTabId: null
    };

    function initNotepad() {
      const stored = localStorage.getItem('notepad_state');
      if (stored) {
        try {
          notepadState = JSON.parse(stored);
        } catch (e) {
          seedDefaultTab();
        }
      } else {
        seedDefaultTab();
      }
      renderTabs();
    }

    function seedDefaultTab() {
      notepadState = {
        tabs: [
          { id: 'welcome', name: 'Welcome.txt', content: 'Welcome to Ubuntu Notepad!\n\nThis system persists all your tabs and contents perfectly in your browser\'s local storage.\n\nDouble click tab labels to rename!' }
        ],
        activeTabId: 'welcome'
      };
      saveNotepad();
    }

    function saveNotepad() {
      localStorage.setItem('notepad_state', JSON.stringify(notepadState));
    }

    function renderTabs() {
      const tabsContainer = document.getElementById('tabs');
      const editor = document.getElementById('editor');

      tabsContainer.innerHTML = '';

      notepadState.tabs.forEach(tab => {
        const tabEl = document.createElement('div');
        tabEl.className = `tab ${tab.id === notepadState.activeTabId ? 'active' : ''}`;
        tabEl.dataset.id = tab.id;

        tabEl.innerHTML = `
          <span class="tab-title" title="Double-click to rename">${tab.name}</span>
          <span class="tab-close" data-id="${tab.id}" title="Close Tab">×</span>
        `;

        tabsContainer.appendChild(tabEl);
      });

      // Handle text area accessibility & fill content
      const activeTab = notepadState.tabs.find(t => t.id === notepadState.activeTabId);
      if (activeTab) {
        editor.value = activeTab.content;
        editor.disabled = false;
        editor.placeholder = "Write your text content here...";
      } else {
        editor.value = '';
        editor.disabled = true;
        editor.placeholder = "No tabs open. Click '+' to start writing!";
      }
    }

    // Create New Tab
    document.getElementById('new-tab').addEventListener('click', () => {
      const newId = 'tab_' + Date.now();
      const newTab = {
        id: newId,
        name: `Untitled ${notepadState.tabs.length + 1}`,
        content: ''
      };
      notepadState.tabs.push(newTab);
      notepadState.activeTabId = newId;
      saveNotepad();
      renderTabs();
      document.getElementById('editor').focus();
    });

    // Click Tab (Switch or Close)
    document.getElementById('tabs').addEventListener('click', (e) => {
      const tabClose = e.target.closest('.tab-close');
      if (tabClose) {
        e.stopPropagation();
        const idToClose = tabClose.dataset.id;
        notepadState.tabs = notepadState.tabs.filter(t => t.id !== idToClose);

        if (notepadState.activeTabId === idToClose) {
          if (notepadState.tabs.length > 0) {
            notepadState.activeTabId = notepadState.tabs[notepadState.tabs.length - 1].id;
          } else {
            notepadState.activeTabId = null;
          }
        }
        saveNotepad();
        renderTabs();
        return;
      }

      const tabEl = e.target.closest('.tab');
      if (tabEl) {
        notepadState.activeTabId = tabEl.dataset.id;
        saveNotepad();
        renderTabs();
      }
    });

    // Rename Tab via Double Click
    document.getElementById('tabs').addEventListener('dblclick', (e) => {
      const tabTitle = e.target.closest('.tab-title');
      if (tabTitle) {
        const tabEl = tabTitle.closest('.tab');
        const tabId = tabEl.dataset.id;
        const targetTab = notepadState.tabs.find(t => t.id === tabId);
        if (!targetTab) return;

        const originalName = targetTab.name;
        const newName = prompt('Enter a new name for this tab:', originalName);
        if (newName && newName.trim() !== '') {
          targetTab.name = newName.trim();
          saveNotepad();
          renderTabs();
        }
      }
    });

    // Handle Content modification
    document.getElementById('editor').addEventListener('input', (e) => {
      const activeTab = notepadState.tabs.find(t => t.id === notepadState.activeTabId);
      if (activeTab) {
        activeTab.content = e.target.value;
        saveNotepad();
      }
    });


    /* ================= INITIALIZATION ================= */
    window.addEventListener('DOMContentLoaded', () => {
      const screenWidth = window.innerWidth;
      const screenHeight = window.innerHeight;

      // Position Windows nicely
      const filesWin = document.getElementById('files-window');
      filesWin.style.left = Math.max(90, (screenWidth - 520) / 2 - 30) + 'px';
      filesWin.style.top = Math.max(60, (screenHeight - 390) / 2 - 30) + 'px';

      const notepadWin = document.getElementById('notepad-window');
      notepadWin.style.left = Math.max(120, (screenWidth - 520) / 2 + 30) + 'px';
      notepadWin.style.top = Math.max(80, (screenHeight - 390) / 2 + 30) + 'px';

      // Start Applications
      renderFiles();
      initNotepad();
    });
  </script>
</body>
</html>
